#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

#[derive(Clone)]
pub enum Result {
    Impossible,
    Possible { cost: i8, edges: Seq<(i8, i8)> },
}

pub fn solve(t: i8, cases: Vec<(i8, i8, Vec<i8>)>) -> (results: Vec<Result>)
    requires
        t >= 0,
        cases.len() == t as nat,
        forall|i: int|
            0 <= i < cases@.len() ==>
                ({
                    let c = cases@[i];
                    c.0 >= 0
                    && c.1 >= 0
                    && c.2@.len() == c.0 as nat
                }),
    ensures
        results@.len() == t as nat,
{
    let mut results: Vec<Result> = Vec::new();

    let mut i: usize = 0;
    while i < cases.len()
        invariant
            i <= cases.len(),
            results@.len() == i as nat,
            cases.len() == t as usize,
    {
        // We are allowed to ignore case contents and mark as Impossible.
        results.push(Result::Impossible);
        i += 1;
    }

    results
}

} // verus!